import{_ as a,o as r,c as i,a2 as l}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Симбиотическая Конституция: Общие Принципы","description":"","frontmatter":{},"headers":[],"relativePath":"ru/40-共生宪法总纲.md","filePath":"ru/40-共生宪法总纲.md","lastUpdated":null}'),e={name:"ru/40-共生宪法总纲.md"};function o(d,t,n,s,h,p){return r(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="симбиотическая-конституция-общие-принципы" tabindex="-1">Симбиотическая Конституция: Общие Принципы <a class="header-anchor" href="#симбиотическая-конституция-общие-принципы" aria-label="Permalink to &quot;Симбиотическая Конституция: Общие Принципы&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>40</td></tr><tr><td>Модуль</td><td>Правовая система и структура управления</td></tr><tr><td>Ключевые слова</td><td>Симбиотическая Конституция, Основной закон, Равенство Десяти Тысяч Рас, Симбиотические права, Конституционные принципы</td></tr></tbody></table><h2 id="i-конституционныи-статус-и-история-создания" tabindex="-1">I. Конституционный статус и история создания <a class="header-anchor" href="#i-конституционныи-статус-и-история-создания" aria-label="Permalink to &quot;I. Конституционный статус и история создания&quot;">​</a></h2><p><em>Симбиотическая Конституция</em> — основной закон Симбиотической Цивилизации Якоря в Изначальной Вселенной Ваньлин Хэнмао (Вселенной Хэнъюань), обладающий высшей юридической силой. Все законы, административные регламенты, местные нормативные акты и автономные правила не должны противоречить Конституции; все организации и индивиды обязаны принимать Конституцию как основное руководство к действию и несут обязанность защищать достоинство Конституции и обеспечивать её исполнение.</p><p>Симбиотическая Конституция была принята в момент официального основания Симбиотической Цивилизации Якоря. Её ключевая цель — на уровне основного закона закрепить цивилизационный фундамент «против хищничества, за симбиоз», зафиксировав в высшей юридической форме ключевую философию Симбиотической Цивилизации Якоря — возвращение существам права выбора судьбы и эволюции, больше труда больше награды, самопроизрастание и саморазвитие, дорога для каждого, совместное продвижение Десяти Тысяч Рас — чтобы предотвратить реставрацию хищнических институтов.</p><h2 id="ii-основные-принципы-конституции" tabindex="-1">II. Основные принципы Конституции <a class="header-anchor" href="#ii-основные-принципы-конституции" aria-label="Permalink to &quot;II. Основные принципы Конституции&quot;">​</a></h2><p>Симбиотическая Конституция устанавливает семь основных принципов, составляющих ценностный фундамент всей правовой системы:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Содержание</th></tr></thead><tbody><tr><td>Принцип равенства Десяти Тысяч Рас</td><td>Все формы жизни, независимо от расы, культивации или происхождения, равны перед законом</td></tr><tr><td>Принцип симбиотической эволюции</td><td>Эволюция индивида не должна осуществляться за счёт эволюционных прав других индивидов или коллектива</td></tr><tr><td>Принцип больше труда — больше награды</td><td>Распределение ресурсов основано на вкладе; против нетрудового обогащения и хищнического присвоения</td></tr><tr><td>Принцип самопроизрастания и саморазвития</td><td>Уважение права каждого существа самостоятельно выбирать путь эволюции; против принудительной ассимиляции и контроля сознания</td></tr><tr><td>Принцип дороги для каждого</td><td>Государство и цивилизация обязаны обеспечить каждому существу базовый путь эволюции и гарантию ресурсов</td></tr><tr><td>Принцип реальности как основы</td><td>Право признаёт реальный мир единственной истинной основой; вымышленные конструкции не имеют юридической силы</td></tr><tr><td>Принцип устойчивости</td><td>Всякое развитие должно учитывать устойчивость Первоосновы Вселенной; против хищнического истощения</td></tr></tbody></table><h2 id="iii-основные-права-граждан-всех-существ" tabindex="-1">III. Основные права граждан (всех существ) <a class="header-anchor" href="#iii-основные-права-граждан-всех-существ" aria-label="Permalink to &quot;III. Основные права граждан (всех существ)&quot;">​</a></h2><p>Симбиотическая Конституция предоставляет всем формам жизни, обладающим способностью восприятия во Вселенной Хэнъюань, следующие основные права:</p><ol><li><strong>Право выбора эволюции</strong>: каждое существо имеет право свободно выбирать систему культивации, путь эволюции и образ жизни; никакая организация или индивид не могут принудительно вмешиваться.</li><li><strong>Право доступа к культивационным ресурсам</strong>: каждое существо имеет право бесплатно получать базовые методы Трёхсот Изначальных Систем Культивации и получать необходимую поддержку культивационными ресурсами через Механизм Совместного Подряда.</li><li><strong>Право равной защиты</strong>: каждое существо пользуется равным отношением в применении закона, распределении ресурсов, образовании и медицине; дискриминация по признаку расы, культивации или происхождения запрещена.</li><li><strong>Право симбиотического участия</strong>: каждое существо имеет право участвовать в принятии решений и надзоре по общественным делам, выражая мнения и реализуя права через симбиотическую сеть.</li><li><strong>Право сохранения культуры</strong>: каждая раса и цивилизация имеет право сохранять свои культурные традиции, язык, письменность и обычаи; симбиотическая цивилизация уважает культурное разнообразие.</li><li><strong>Право на защиту и обжалование</strong>: каждое существо при нарушении его прав имеет право получить защиту через судебную систему и подавать жалобы и обвинения на противоправные действия.</li></ol><h2 id="iv-основные-обязанности" tabindex="-1">IV. Основные обязанности <a class="header-anchor" href="#iv-основные-обязанности" aria-label="Permalink to &quot;IV. Основные обязанности&quot;">​</a></h2><p>Права и обязанности взаимны; Симбиотическая Конституция одновременно устанавливает основные обязанности всех существ:</p><ol><li><strong>Обязанность соблюдать Конституцию и законы</strong></li><li><strong>Обязанность поддерживать симбиотический порядок и общественные интересы</strong></li><li><strong>Обязанность участвовать в труде и вкладе в соответствии с законом</strong> (зеркальная сторона принципа больше труда — больше награды)</li><li><strong>Обязанность защищать Первооснову Вселенной и экологическую среду</strong></li><li><strong>Обязанность уважать законные права других существ</strong></li><li><strong>Обязанность в пределах своих возможностей наставлять начинающих культиваторов</strong> (правовая основа сети наставников)</li></ol><h2 id="v-институциональное-устроиство-государства-цивилизации" tabindex="-1">V. Институциональное устройство государства (цивилизации) <a class="header-anchor" href="#v-институциональное-устроиство-государства-цивилизации" aria-label="Permalink to &quot;V. Институциональное устройство государства (цивилизации)&quot;">​</a></h2><p>Симбиотическая Конституция устанавливает структуру управления симбиотической цивилизации, реализуя механизм «разделения и уравновешивания трёх властей» — Собрание Якоря, Симбиотический Исполнительный Комитет и Симбиотический Суд:</p><ul><li><strong>Собрание Якоря</strong>: высший орган власти, состоящий из представителей Десяти Тысяч Рас пропорционально, осуществляющий законодательную власть и право решения важнейших вопросов</li><li><strong>Симбиотический Исполнительный Комитет</strong>: высший административный орган, отвечающий за исполнение Конституции и законов и повседневное управление</li><li><strong>Симбиотический Суд</strong>: высший судебный орган, независимо осуществляющий судебную власть, отвечающий за конституционный контроль и рассмотрение важнейших дел</li></ul><p>Кроме того, создан «Надзорный Комитет Якоря» как независимый надзорный орган, отвечающий за надзор за всеми органами власти, предотвращение злоупотребления властью и возрождения хищнических практик.</p><h2 id="vi-изменение-конституции-и-гарантии" tabindex="-1">VI. Изменение Конституции и гарантии <a class="header-anchor" href="#vi-изменение-конституции-и-гарантии" aria-label="Permalink to &quot;VI. Изменение Конституции и гарантии&quot;">​</a></h2><p>Изменение Симбиотической Конституции вступает в силу только после принятия большинством в две трети и более голосов Собрания Якоря и одобрения простым большинством на всенародном референдуме. Эта строгая процедура гарантирует стабильность Конституции как основного закона, не позволяя группам краткосрочных интересов легко искажать фундамент цивилизации.</p><p>Гарантии исполнения Конституции включают: систему конституционного контроля (Симбиотический Суд имеет право признавать недействительными законы, противоречащие Конституции), систему конституционного судопроизводства (существа могут подавать иски непосредственно на основании Конституции) и систему конституционной присяги (все государственные служащие при вступлении в должность обязаны принести присягу на верность Конституции).</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p><em>Симбиотическая Конституция</em> — правовой фундамент Симбиотической Цивилизации Якоря и высшая декларация антихищничества. Она превращает «симбиоз» из идеи в исполнительную, защищаемую и гарантируемую правовую систему, обеспечивая фундаментальную правовую основу для совместного продвижения Десяти Тысяч Рас. Все последующие отраслевые законы принимаются на основе этой Конституции.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>03-共生文明宪章 (Хартия Симбиотической Цивилизации)</li><li>41-共生劳动法 (Симбиотический Трудовой Закон)</li><li>48-司法体系与裁决机制 (Судебная система и механизмы правосудия)</li><li>49-治理框架与权力制衡 (Структура управления и баланс властей)</li></ul>',25)])])}const u=a(e,[["render",o]]);export{g as __pageData,u as default};
